OR  `addr`.`address` LIKE '%bh%' ESCAPE '!'
OR  `mobile` LIKE '%bh%' ESCAPE '!'
OR  `a`.`name` LIKE '%bh%' ESCAPE '!'
OR  `city` LIKE '%bh%' ESCAPE '!'
OR  `state` LIKE '%bh%' ESCAPE '!'
OR  `country` LIKE '%bh%' ESCAPE '!'
OR  `pincode` LIKE '%bh%' ESCAPE '!'
 )
AND `user_id` = '1'
